  {
   "@type": "Question",
   "name": "My dog had diarrhea once. Do I need a vet?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "If it's once or twice and your dog is eating and playing normally, many owners watch for about a day. If there's blood, vomiting or lethargy, or it lasts more than a day, see a vet."
   }
  },
  {
   "@type": "Question",
   "name": "What's the most common cause of diarrhea in dogs?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Minor causes are common, like a sudden food switch, eating treats or human food, or stress. It can also be parasites, a virus or pancreatitis, so if it keeps going, your dog needs tests."
   }
  },
  {
   "@type": "Question",
   "name": "Should I stop feeding my dog when they have diarrhea?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Fasting your dog for a long time on your own isn't recommended. Puppies and small dogs in particular can develop low blood sugar and dehydration. Ask your vet how to feed them."
   }
  },
  {
   "@type": "Question",
   "name": "Can I give my dog human anti-diarrhea medicine?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Human medicine can be dangerous for dogs. Only use medicine your vet prescribes."
   }
  },
  {
   "@type": "Question",
   "name": "My puppy has diarrhea and is vomiting.",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "If your puppy hasn't finished their vaccines, it could be a virus such as parvo, so go to the vet right away."
   }
  }
 ]
